    uint32_t snapshot_ts;
    uint32_t active_txns[MAX_ACTIVE_TXNS];
    int num_active;
} snapshot_t;

typedef struct txn_t {
    uint32_t txn_id;
    snapshot_t snapshot;
    bool aborted;
    uint8_t _pad[3];
    tuple_version_t *write_set[65];
} txn_t;

typedef struct mvcc_db_t {
    tuple_version_t *index[1024];
} mvcc_db_t;

static bool mvcc_is_active(uint32_t txn_id, snapshot_t *snap) {
    for (int i = 0; i < snap->num_active; i++) {
        if (snap->active_txns[i] == txn_id) return true;
    }
    return false;
}

bool mvcc_is_visible(tuple_version_t *tuple, txn_t *txn) {
    if (tuple->xmin > txn->snapshot.snapshot_ts) {
        if (tuple->xmin != txn->txn_id) return false;
    } else {
        if (mvcc_is_active(tuple->xmin, &txn->snapshot) && tuple->xmin != txn->txn_id) return false;
    }

    if (tuple->xmax == INF_TIMESTAMP) return true;
    if (tuple->xmax > txn->snapshot.snapshot_ts) return true;
    if (mvcc_is_active(tuple->xmax, &txn->snapshot) && tuple->xmax != txn->txn_id) return true;

    return false;
}

int mvcc_read(mvcc_db_t *db, txn_t *txn, uint32_t key, uint32_t *out_value) {
    tuple_version_t *curr = db->index[key];
    while (curr) {
        if (mvcc_is_visible(curr, txn)) {
            *out_value = curr->value;
            return MVCC_OK;
        }
        curr = curr->prev;
    }
    return MVCC_ERR_NOT_FOUND;
}

int mvcc_update(mvcc_db_t *db, txn_t *txn, uint32_t key, uint32_t new_value) {
    tuple_version_t *head = db->index[key];
    if (head) {
        if (head->xmax != INF_TIMESTAMP || head->xmin > txn->snapshot.snapshot_ts) {
            return MVCC_ERR_SERIALIZATION_FAILURE;
        }
    }
    tuple_version_t *new_tuple = (tuple_version_t*)malloc(sizeof(tuple_version_t));
    new_tuple->xmin = txn->txn_id;
    new_tuple->xmax = INF_TIMESTAMP;
    new_tuple->key = key;
    new_tuple->value = new_value;
    new_tuple->prev = head;

    if (head) head->xmax = txn->txn_id;
    db->index[key] = new_tuple;

    for (int i = 0; i < 65; i++) {
        if (txn->write_set[i] == NULL) {
            txn->write_set[i] = new_tuple;
            break;
        }
    }
    return MVCC_OK;
}

void mvcc_abort(mvcc_db_t *db, txn_t *txn) {
    for (int i = 64; i >= 0; i--) {
        if (txn->write_set[i] != NULL) {
            tuple_version_t *v = txn->write_set[i];
            if (db->index[v->key] == v) {
                db->index[v->key] = v->prev;
            }
            if (v->prev) {
                v->prev->xmax = INF_TIMESTAMP;
            }
            free(v);
            txn->write_set[i] = NULL;
        }
    }
    txn->aborted = true;
}

int mvcc_vacuum(mvcc_db_t *db, uint32_t oldest_active_ts) {
    int count = 0;
    for (int i = 0; i < 1024; i++) {
        tuple_version_t *curr = db->index[i];
        tuple_version_t *prev_ptr = NULL;
        while (curr) {
            if (curr != db->index[i] && curr->xmax != INF_TIMESTAMP && curr->xmax < oldest_active_ts) {
                tuple_version_t *to_free = curr;
                if (prev_ptr) {
                    prev_ptr->prev = curr->prev;
                    curr = curr->prev;
                } else {
                    db->index[i] = curr->prev;
                    curr = curr->prev;
                }
                free(to_free);
                count++;
            } else {
                prev_ptr = curr;
                curr = curr->prev;
            }
        }
    }
    return count;
}

int main() {
